import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";

// Vendored from `@/app/console/lib/terminal` (unresolvable in this sandbox) — unchanged, pure.
const DEFAULT_TERMINAL_FONT_SIZE = 12;
const MIN_TERMINAL_FONT_SIZE = 8;
const MAX_TERMINAL_FONT_SIZE = 28;
const TERMINAL_FONT_STEP = 1;
function clampFontSize(size) {
  if (!Number.isFinite(size)) return DEFAULT_TERMINAL_FONT_SIZE;
  return Math.min(MAX_TERMINAL_FONT_SIZE, Math.max(MIN_TERMINAL_FONT_SIZE, Math.round(size)));
}
function adjustFontSize(current, steps) {
  return clampFontSize(current + steps * TERMINAL_FONT_STEP);
}

export function TerminalFontSizeCard() {
  const [terminalFontSize, setTerminalFontSize] = useState(DEFAULT_TERMINAL_FONT_SIZE);

  return (
    <Card title="Terminal font size" hint="also bound to Ctrl + / Ctrl - / Ctrl 0">
      <Row gap={14}>
        <Button
          aria-label="Decrease terminal font size"
          disabled={terminalFontSize <= MIN_TERMINAL_FONT_SIZE}
          onClick={() => setTerminalFontSize(adjustFontSize(terminalFontSize, -1))}
        >−</Button>
        {/* eslint-disable-next-line no-restricted-syntax -- range slider; no shared primitive for <input type="range"> */}
        <input
          type="range"
          aria-label="Terminal font size"
          min={MIN_TERMINAL_FONT_SIZE}
          max={MAX_TERMINAL_FONT_SIZE}
          value={terminalFontSize}
          onChange={(e) => setTerminalFontSize(Number(e.target.value))}
          style={{ flex: 1, accentColor: "var(--accent)" }}
        />
        <Button
          aria-label="Increase terminal font size"
          disabled={terminalFontSize >= MAX_TERMINAL_FONT_SIZE}
          onClick={() => setTerminalFontSize(adjustFontSize(terminalFontSize, +1))}
        >+</Button>
        <Text as="span" mono size="md" style={{
          color: "var(--fg)",
          minWidth: 48, textAlign: "right",
        }}>{terminalFontSize}px</Text>
        <Button
          variant="ghost"
          onClick={() => setTerminalFontSize(DEFAULT_TERMINAL_FONT_SIZE)}
          disabled={terminalFontSize === DEFAULT_TERMINAL_FONT_SIZE}
        >reset</Button>
      </Row>
      <Box
        className="mono"
        pad={[10, 12]} bg="var(--bg-canvas)" border="soft" radius={6} style={{
          marginTop: 14,
          fontSize: terminalFontSize, color: "var(--fg-muted)",
          whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
        }}
      >$ claude — the quick brown fox jumps over 1234567890</Box>
    </Card>
  );
}
